import{z as n,x as i,o as E,c as B,q as d,j as r,D as t,d as e,s as m,S as s,b as l}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"权重衰减的豁免：嵌入与 norm","description":"","frontmatter":{"title":"权重衰减的豁免：嵌入与 norm","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/weight-decay-exemptions.md","filePath":"llm/weight-decay-exemptions.md","lastUpdated":1791063341000}'),A={name:"llm/weight-decay-exemptions.md"};function p(g,a,D,b,h,u){const o=i("Mermaid");return E(),B("div",null,[a[2]||(a[2]=d('<h1 id="权重衰减的豁免-嵌入与-norm" tabindex="-1">权重衰减的豁免：嵌入与 norm <a class="header-anchor" href="#权重衰减的豁免-嵌入与-norm" aria-label="Permalink to &quot;权重衰减的豁免：嵌入与 norm&quot;">​</a></h1><div class="epigraph"><p>解耦衰减对每个参数乘 $1-\\eta\\lambda$；把这一乘用在归一化增益和查找表上，等于按步数把尺度往 0 拉，而那两处的尺度本应被另外的课钉住。</p><footer>—— Loshchilov &amp; Hutter, ICLR 2019；预训练配方中的分组见 GPT-3 / Llama 一类报告</footer></div><p><a href="/llm/lr-sensitivity-mup-practice">上一课</a>要求扫 \\(\\eta\\) 时声明 \\(\\lambda\\) 怎么走。缺口是：<strong>哪些参数根本不该进衰减组</strong>。AdamW 的 \\(W\\leftarrow W-\\eta\\lambda W\\) 对矩阵权有正则与尺度控制的双重作用；对 RMSNorm 的 \\(\\gamma\\)、对嵌入行，同一乘会直接对抗 <a href="/llm/activation-scale-drift">激活漂移</a> 与 <a href="/llm/embedding-init-scale">嵌入初始化</a> 想保留的范数。主干 <a href="/llm/adamw">AdamW</a> 已警告 bias / LN 豁免；本课写成稳定性条款，并处理嵌入该不该豁免的分歧。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>LN / RMSNorm 的 \\(\\gamma\\) 起步为 1，职责是通道尺度。每步乘 \\(1-\\eta\\lambda\\)，等于强制 \\(\\gamma\\to 0\\)。训练还能靠 CE 把 \\(\\gamma\\) 撑住，但衰减与损失在打架：LSE 课里写过，z-loss 要把 logits 往下拉，衰减要把 \\(\\gamma\\) 往下拉，嵌入豁免又让输入范数涨——三条力同时作用在尺度上，日志无法归因。偏置同理：衰减把 \\(b\\) 往 0 拉，而 \\(b\\) 常常在学频率先验。</p><p>嵌入更麻烦。Loshchilov 的图像实验倾向衰减权重、豁免 bias。语言模型的 \\(E\\) 既是输入也常是（tied 时）输出。衰减嵌入：稀有行被反复乘小于 1 的因子、又很少被梯度更新，行范数趋向 0，变成死 token。不衰减：热门行范数可以涨，总线 RMS 涨。GPT-2 / GPT-3 / Llama 的具体分组不完全相同，本课不编造某一家的表，只要求<strong>显式列出</strong>四组：隐藏矩阵、嵌入、输出头、norm/bias。</p><p><span class="marginnote">把嵌入表想成一间图书馆：热门 token 是常被借的书，梯度管理员不断把它摆回书架正中央；稀有 token 躺在角落没人碰，衰减机制却每天把所有书往角落推一毫米。日积月累，角落里的书就被推得「不存在」了——这就是死 token 的直觉图像。</span></p><p><span class="marginnote">「weight_decay=0.1」若应用在未分组的 <code>model.parameters()</code> 上，LN 和嵌入都在里面。这是实现默认，不是论文定理。读配置必须读 optimizer param groups。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>推荐起点（可被消融推翻）：</p><ul><li><strong>衰减：</strong> 注意力与 FFN 的线性矩阵。</li><li><strong>不衰减：</strong> 所有 norm 的 \\(\\gamma,\\beta\\)、所有 bias。</li><li><strong>嵌入：</strong> 默认不衰减或使用更小的 \\(\\lambda\\)；tied 时与输出头同一政策。</li><li><strong>untied 输出头：</strong> 可衰减，作为对抗 LSE 发散的一条力，但 α 与 \\(\\lambda\\) 不要同时从零加到头。</li></ul><p><span class="marginnote">「解耦」指缩小权重这一步从梯度更新里单独拆出来执行。SGD 时代衰减混在梯度里，Adam 还会把这一项除出奇怪的大小；AdamW 改成更新后统一乘 \\((1-\\eta\\lambda)\\)，对所有参数一视同仁——而这份一视同仁，恰恰是它误伤 norm 增益与嵌入长尾的原因。</span></p><p>μP 下 \\(\\lambda\\) 是否随宽度变，跟主干 weight-decay-mup 课，不在这里另造一列。本课只决定<strong>集合</strong>，不决定 \\(\\lambda(d)\\)。</p><p>验收：训练中途打印 \\(\\|\\gamma\\|\\)、嵌入行范数的分位数。\\(\\gamma\\) 若系统性掉到 \\(\\ll 1\\)，衰减组包进了 norm。嵌入行范数若双峰（热门极大、长尾近 0），考虑把嵌入拆出衰减或给长尾一个地板。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>解耦衰减与梯度无关，稀疏行也会被每步缩小。这和「权重衰减约等于先验」在稠密卷积上的故事不同：卷积核几乎每步都有梯度，衰减与更新平衡；嵌入长尾没有平衡项。norm 的 \\(\\gamma\\) 每步都有梯度，但目标尺度是 \\(O(1)\\) 而不是 \\(O(0)\\)，衰减的不动点与职责冲突。</p>',16)),(E(),r(s,null,{default:t(()=>[m(o,{id:"mermaid-65",class:"mermaid",graph:"flowchart%20TD%0A%20%20STEP%5B%22%E6%AF%8F%E4%B8%AA%E8%AE%AD%E7%BB%83%E6%AD%A5%22%5D%20--%3E%20MUL%5B%22%E8%A1%B0%E5%87%8F%E7%BB%84%E5%8F%82%E6%95%B0%E7%BB%9F%E4%B8%80%E4%B9%98%201-eta*lambda%22%5D%0A%20%20MUL%20--%3E%20HOT%5B%22%E7%83%AD%E9%97%A8%E5%B5%8C%E5%85%A5%E8%A1%8C%3A%20%E6%A2%AF%E5%BA%A6%E6%9B%B4%E6%96%B0%E6%8A%B5%E6%B6%88%E7%BC%A9%E5%B0%8F%22%5D%0A%20%20MUL%20--%3E%20COLD%5B%22%E7%A8%80%E6%9C%89%E5%B5%8C%E5%85%A5%E8%A1%8C%3A%20%E5%87%A0%E4%B9%8E%E7%AD%89%E4%B8%8D%E5%88%B0%E6%A2%AF%E5%BA%A6%22%5D%0A%20%20HOT%20--%3E%20OK%5B%22%E8%A1%8C%E8%8C%83%E6%95%B0%E7%BB%B4%E6%8C%81%22%5D%0A%20%20COLD%20--%3E%20DEAD%5B%22%E8%A1%8C%E8%8C%83%E6%95%B0%E6%BB%91%E5%90%91%200%20%E2%86%92%20%E6%AD%BB%20token%22%5D%0A%20%20DEAD%20--%3E%20CHK%5B%22%E9%AA%8C%E6%94%B6%E4%BF%A1%E5%8F%B7%3A%20%E8%A1%8C%E8%8C%83%E6%95%B0%E5%88%86%E4%BD%8D%E6%95%B0%E5%8F%8C%E5%B3%B0%22%5D%0A%20%20OK%20--%3E%20MON%5B%22%E9%AA%8C%E6%94%B6%E4%BF%A1%E5%8F%B7%3A%20%E5%88%86%E4%BD%8D%E6%95%B0%E5%B9%B3%E7%A8%B3%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("p",null,[l("span",{class:"marginnote"},"数字代入：取 \\(\\eta=0.001\\)、\\(\\lambda=0.1\\)，每步乘子是 \\(1-0.0001=0.9999\\)；一万步后剩 \\(0.9999^{10000}\\approx 0.37\\)。若这期间几乎没有梯度把参数推回去，一行嵌入就无声无息缩到三分之一。对每步都有梯度的矩阵这是平衡，对长尾嵌入行是慢性死亡。")],-1)),a[4]||(a[4]=l("p",null,"与 z-loss：两者都想压输出尺度。衰减 \\(W_{\\mathrm{out}}\\) 压的是权重范数，z-loss 压的是 LSE。只衰减、不 z-loss，LSE 仍可因 \\(h\\) 的 \\(\\gamma\\) 变大而涨。只豁免、不 z-loss，尺度更容易飞。稳定性配方应写成三列：衰减集合、z-loss α、是否 cap，而不是一个「正则系数」。",-1)),a[5]||(a[5]=l("h2",{id:"边界",tabindex:"-1"},[e("边界 "),l("a",{class:"header-anchor",href:"#边界","aria-label":'Permalink to "边界"'},"​")],-1)),a[6]||(a[6]=l("p",null,[e("本课不讨论把衰减改成对激活的正则。也不把「嵌入不衰减」写成必然提高下游——它首先是避免死行与尺度打架。下一课开始把"),l("strong",null,"多检查点"),e("合成更稳的推理权重：EMA 与平均，不再改单步更新。")],-1)),(E(),r(s,null,{default:t(()=>[m(o,{id:"mermaid-78",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E5%85%A8%E4%BD%93%E5%8F%82%E6%95%B0%22%5D%20--%3E%20MAT%5B%22%E7%BA%BF%E6%80%A7%E7%9F%A9%E9%98%B5%EF%BC%9A%E8%A1%B0%E5%87%8F%22%5D%0A%20%20P%20--%3E%20EMB%5B%22%E5%B5%8C%E5%85%A5%EF%BC%9A%E9%80%9A%E5%B8%B8%E8%B1%81%E5%85%8D%E6%88%96%E5%B0%8F%20lambda%22%5D%0A%20%20P%20--%3E%20NM%5B%22norm%20%E4%B8%8E%20bias%EF%BC%9A%E8%B1%81%E5%85%8D%22%5D%0A%20%20P%20--%3E%20OUT%5B%22%E8%BE%93%E5%87%BA%E5%A4%B4%EF%BC%9A%E6%94%BF%E7%AD%96%E6%98%BE%E5%BC%8F%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l("h2",{id:"小结",tabindex:"-1"},[e("小结 "),l("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[8]||(a[8]=l("ul",null,[l("li",null,"AdamW 的 \\(1-\\eta\\lambda\\) 对 norm 增益是错误的尺度先验，对嵌入长尾会造成死行。"),l("li",null,"必须写清四组：矩阵、嵌入、输出头、norm/bias；禁止一个全局 \\(\\lambda\\)。"),l("li",null,"衰减、z-loss、cap 是三条尺度力，要能单独开关。"),l("li",null,"验收看 \\(\\|\\gamma\\|\\) 与嵌入行范数分位数，不看「配置里写了 0.1」。"),l("li",null,"出处：Loshchilov & Hutter, ICLR 2019；GPT-3 / Llama 预训练中的参数分组实践。")],-1))])}const f=n(A,[["render",p]]);export{c as __pageData,f as default};
